import{decompress}from"./codec/deflate.js";import{b64decode}from"./codec/base64.js";import{minifyJS}from"./minify/js.js";const PAGE_URL=new URL("data:application/gzip;base64,",import.meta.url);let cached=null;async function bytesOf(url){const s=String(url);if(s.startsWith('data:'))return b64decode(s.slice(s.indexOf(',')+1));const r=await fetch(url);if(!r.ok)throw new Error('bundle '+r.status);return new Uint8Array(await r.arrayBuffer());}
function pageRuntime(){if(!cached){cached=(async()=>{const gz=await bytesOf(PAGE_URL);if(gz[0]!==0x1f||gz[1]!==0x8b)throw new Error('not a bundle');return minifyJS(new TextDecoder().decode(await decompress(gz,'gzip')));})();cached.catch(()=>{cached=null;});}
return cached;}
export{pageRuntime};